        for i,a in enumerate(centers):
            color=grid[r][a]
            if color==0: continue
            for b in centers[i+1:]:
                if grid[r][b]==color:
                    for c in range(a+1,b):
                        if grid[r][c]==0: out[r][c]=color
    for c in centers:
        for i,a in enumerate(centers):
            color=grid[a][c]
            if color==0: continue
            for b in centers[i+1:]:
                if grid[b][c]==color:
                    for r in range(a+1,b):
                        if grid[r][c]==0: out[r][c]=color
    return out
