def transform(grid):
    out=[row[:] for row in grid]
    # Inferred connectors project the distinctive panel's color outward from
    # its 2x2 interior through adjacent background gutters.
    h,w=len(grid),len(grid[0])
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color not in (4,8):
                continue
            # Panel colors occupy 2x2 blocks; connect neighboring matching panels
            # through background only when a matching block is found in line.
            for dr,dc in ((0,1),(1,0),(0,-1),(-1,0)):
                rr,cc=r+dr,c+dc
                while 0<=rr<h and 0<=cc<w:
                    if grid[rr][cc]==color:
                        rr+=dr; cc+=dc; continue
                    if grid[rr][cc]!=0: break
                    # extend through gutter towards a second identical panel
                    endr,endc=rr,cc
                    while 0<=endr<h and 0<=endc<w and grid[endr][endc]==0:
                        endr+=dr; endc+=dc
                    if 0<=endr<h and 0<=endc<w and grid[endr][endc]==color:
                        out[rr][cc]=color
                    break
    return out
