def transform(grid):
    out=[row[:] for row in grid]
    # Locate the repeated 5x5 framed panels and connect equal interior colors
    # along aligned rows/columns, painting only the intervening blank gutters.
    row_starts=[1,8,16,23]
    col_starts=[1,8,15,22]
    h,w=len(grid),len(grid[0])
    for ri,r0 in enumerate(row_starts):
        for inner_r in range(r0+1,min(r0+4,h)):
            for j,a in enumerate(col_starts):
                color=grid[inner_r][a+1]
                if color==0: continue
                for k in range(j+1,len(col_starts)):
                    b=col_starts[k]
                    if grid[inner_r][b+1]==color:
                        for p in range(a+5,b):
                            if grid[inner_r][p]==0: out[inner_r][p]=color
    for ci,c0 in enumerate(col_starts):
        for inner_c in range(c0+1,min(c0+4,w)):
            for j,a in enumerate(row_starts):
                color=grid[a+1][inner_c]
                if color==0: continue
                for k in range(j+1,len(row_starts)):
                    b=row_starts[k]
                    if grid[b+1][inner_c]==color:
                        for p in range(a+5,b):
                            if grid[p][inner_c]==0: out[p][inner_c]=color
    return out
