def transform(grid):
    out=[r[:] for r in grid]
    # Extend the exceptional 8-colored panels into their adjoining two-cell
    # blank gutters, as the demonstrations do for distinctive interior panels.
    row_starts=[1,8,16,23]
    col_starts=[1,8,15,22]
    for ri,r0 in enumerate(row_starts):
        for cj,c0 in enumerate(col_starts):
            color=grid[r0+1][c0+1]
            if color!=8: continue
            # horizontal projections across each adjoining blank gap
            for r in range(r0+1,r0+4):
                for c in range(c0-2,c0):
                    if c>=0 and grid[r][c]==0: out[r][c]=8
                for c in range(c0+5,c0+7):
                    if c<len(grid[0]) and grid[r][c]==0: out[r][c]=8
            # vertical projections across adjoining blank gaps
            for c in range(c0+1,c0+4):
                for r in range(r0-2,r0):
                    if r>=0 and grid[r][c]==0: out[r][c]=8
                for r in range(r0+5,r0+7):
                    if r<len(grid) and grid[r][c]==0: out[r][c]=8
    return out
