def transform(grid):
    out=[row[:] for row in grid]
    # The tile interiors repeat in four-by-four arrangement. Continue matching
    # colored interior cells across the blank two-cell gutters, same row/column.
    row_starts=[1,8,16,23]
    col_starts=[1,8,15,22]
    for r0 in row_starts:
        for r in range(r0+1,r0+4):
            for j in range(3):
                a,b=col_starts[j],col_starts[j+1]
                color=grid[r][a+1]
                if color and color==grid[r][b+1]:
                    for c in range(a+5,b):
                        if grid[r][c]==0: out[r][c]=color
    for c0 in col_starts:
        for c in range(c0+1,c0+4):
            for j in range(3):
                a,b=row_starts[j],row_starts[j+1]
                color=grid[a+1][c]
                if color and color==grid[b+1][c]:
                    for r in range(a+5,b):
                        if grid[r][c]==0: out[r][c]=color
    return out
