def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    rs=[1,8,16,23]
    cs=[1,8,15,22]
    # The dominant interior color is the ordinary panel; all exceptional
    # panel colors project straight out through adjacent blank gutters.
    counts={}
    for r in rs:
        for c in cs:
            color=grid[r+1][c+1]
            counts[color]=counts.get(color,0)+1
    ordinary=max(counts,key=counts.get)
    for r0 in rs:
        for c0 in cs:
            color=grid[r0+1][c0+1]
            if color==ordinary or color==0: continue
            for r in range(r0+1,min(r0+4,h)):
                for c in range(c0-2,c0):
                    if c>=0 and grid[r][c]==0: out[r][c]=color
                for c in range(c0+5,min(c0+7,w)):
                    if grid[r][c]==0: out[r][c]=color
            for c in range(c0+1,min(c0+4,w)):
                for r in range(r0-2,r0):
                    if r>=0 and grid[r][c]==0: out[r][c]=color
                for r in range(r0+5,min(r0+7,h)):
                    if grid[r][c]==0: out[r][c]=color
    return out
