def transform(grid):
    out=[row[:] for row in grid]
    from collections import Counter
    counts=Counter(x for row in grid for x in row if x)
    frame=counts.most_common(1)[0][0]
    inner=Counter(x for row in grid for x in row if x and x!=frame)
    ordinary=inner.most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    # Distinctive tile colors connect collinearly across blank gaps only.
    for r in range(h):
        for color in set(grid[r]):
            if color in (0,frame,ordinary): continue
            positions=[c for c,v in enumerate(grid[r]) if v==color]
            for a,b in zip(positions,positions[1:]):
                for c in range(a+1,b):
                    if grid[r][c]==0: out[r][c]=color
    for c in range(w):
        for color in {grid[r][c] for r in range(h)}:
            if color in (0,frame,ordinary): continue
            positions=[r for r in range(h) if grid[r][c]==color]
            for a,b in zip(positions,positions[1:]):
                for r in range(a+1,b):
                    if grid[r][c]==0: out[r][c]=color
    return out
