def transform(grid):
    out=[r[:] for r in grid]
    row_starts=[1,8,16,23]
    col_starts=[1,8,15,22]
    # Atypical panel interiors project across every blank gutter on their
    # aligned rows and columns, while the intervening panels/frames stay intact.
    from collections import Counter
    colors=[grid[r+1][c+1] for r in row_starts for c in col_starts]
    normal=Counter(colors).most_common(1)[0][0]
    for r0 in row_starts:
        for r in range(r0+1,r0+4):
            if grid[r][col_starts[0]+1] != normal:
                for c in range(len(grid[0])):
                    if grid[r][c]==0: out[r][c]=grid[r][col_starts[0]+1]
            # Any atypical panel in this row projects across gutters on that lane.
            for c0 in col_starts:
                color=grid[r][c0+1]
                if color!=normal and color!=0:
                    for c in range(len(grid[0])):
                        if grid[r][c]==0: out[r][c]=color
    for c0 in col_starts:
        for c in range(c0+1,c0+4):
            for r0 in row_starts:
                color=grid[r0+1][c]
                if color!=normal and color!=0:
                    for r in range(len(grid)):
                        if grid[r][c]==0: out[r][c]=color
    return out
