def transform(grid):
    out=[row[:] for row in grid]
    # Detect the modal interior fill; only less-common interior colors are
    # connector markers. Connect matching markers horizontally/vertically,
    # changing blank gutter cells but preserving all tile/frame cells.
    row_centers=[3,10,18,25]
    col_centers=[3,10,17,24]
    from collections import Counter
    interior=[grid[r][c] for r in row_centers for c in col_centers if grid[r][c] != 0]
    counts=Counter(interior)
    common=counts.most_common(1)[0][0]
    for r in row_centers:
        for color in set(grid[r][c] for c in col_centers):
            if color in (0,common): continue
            positions=[c for c in col_centers if grid[r][c]==color]
            if len(positions)>1:
                for a,b in zip(positions,positions[1:]):
                    for c in range(a+1,b):
                        if grid[r][c]==0: out[r][c]=color
    for c in col_centers:
        for color in set(grid[r][c] for r in row_centers):
            if color in (0,common): continue
            positions=[r for r in row_centers if grid[r][c]==color]
            if len(positions)>1:
                for a,b in zip(positions,positions[1:]):
                    for r in range(a+1,b):
                        if grid[r][c]==0: out[r][c]=color
    return out
