def transform(grid):
    out=[r[:] for r in grid]
    row_starts=[1,8,16,23]
    col_starts=[1,8,15,22]
    row_bands=[(r+1,r+3) for r in row_starts]
    col_bands=[(c+1,c+3) for c in col_starts]
    # Find exceptional interior colors (the modal panel fill is ordinary).
    from collections import Counter
    vals=[grid[r+1][c+1] for r in row_starts for c in col_starts]
    ordinary=Counter(vals).most_common(1)[0][0]
    # Equal exceptional panels on a row project through all intervening gutters.
    for i,(ra,rb) in enumerate(row_bands):
        for j in range(len(col_starts)):
            color=grid[ra][col_bands[j][0]]
            if color in (0,ordinary): continue
            matches=[k for k in range(len(col_starts)) if grid[ra][col_bands[k][0]]==color]
            if len(matches)<2: continue
            left,right=min(matches),max(matches)
            for x in range(left,right):
                c0=col_starts[x]+5
                c1=col_starts[x+1]
                for r in range(ra,rb+1):
                    for c in range(c0,c1):
                        if grid[r][c]==0: out[r][c]=color
    # Equal exceptional panels in a column project through intervening gutters.
    for j,(ca,cb) in enumerate(col_bands):
        for i in range(len(row_starts)):
            color=grid[row_bands[i][0]][ca]
            if color in (0,ordinary): continue
            matches=[k for k in range(len(row_starts)) if grid[row_bands[k][0]][ca]==color]
            if len(matches)<2: continue
            top,bottom=min(matches),max(matches)
            for x in range(top,bottom):
                r0=row_starts[x]+5
                r1=row_starts[x+1]
                for r in range(r0,r1):
                    for c in range(ca,cb+1):
                        if grid[r][c]==0: out[r][c]=color
    return out
