def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Interior colors unlike the panel frame act as ray sources. Rays cross
    # empty gutters and other interiors, replacing them, and stop at frame 4.
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color not in (3,8):
                continue
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                y,x=r+dr,c+dc
                while 0<=y<h and 0<=x<w and grid[y][x]!=4:
                    out[y][x]=color
                    y+=dr
                    x+=dc
    return out
