def transform(grid):
    out=[row[:] for row in grid]
    # Detect the 5x5 framed tiles and their 3x3 interior colors.
    rs=[1,8,16,23]
    cs=[1,8,15,22]
    vals=[[grid[r+1][c+1] for c in cs] for r in rs]
    from collections import Counter
    common=Counter(x for row in vals for x in row).most_common(1)[0][0]
    # Repeated exceptional colors connect across blank gutters only.
    for i in range(4):
        for color in set(vals[i]):
            if color in (0,common): continue
            p=[j for j in range(4) if vals[i][j]==color]
            for a,b in zip(p,p[1:]):
                for r in range(rs[i]+1,rs[i]+4):
                    for c in range(cs[a]+5,cs[b]):
                        if grid[r][c]==0: out[r][c]=color
    for j in range(4):
        for color in {vals[i][j] for i in range(4)}:
            if color in (0,common): continue
            p=[i for i in range(4) if vals[i][j]==color]
            for a,b in zip(p,p[1:]):
                for c in range(cs[j]+1,cs[j]+4):
                    for r in range(rs[a]+5,rs[b]):
                        if grid[r][c]==0: out[r][c]=color
    return out
