def transform(grid):
    out=[row[:] for row in grid]
    row_starts=[1,8,16,23]
    col_starts=[1,8,15,22]
    centers=[[grid[r+1][c+1] for c in col_starts] for r in row_starts]
    # Matching panel colors connect through blank gutters, skipping intervening tiles.
    for i in range(4):
        for j in range(4):
            for k in range(j+1,4):
                color=centers[i][j]
                if color==0 or color!=centers[i][k]: continue
                for x in range(j,k):
                    left=col_starts[x]+5
                    right=col_starts[x+1]
                    for r in range(row_starts[i]+1,row_starts[i]+4):
                        for c in range(left,right):
                            if grid[r][c]==0: out[r][c]=color
    for j in range(4):
        for i in range(4):
            for k in range(i+1,4):
                color=centers[i][j]
                if color==0 or color!=centers[k][j]: continue
                for x in range(i,k):
                    top=row_starts[x]+5
                    bottom=row_starts[x+1]
                    for r in range(top,bottom):
                        for c in range(col_starts[j]+1,col_starts[j]+4):
                            if grid[r][c]==0: out[r][c]=color
    return out
